    efatura: { degisir: ['Entegre et ile entegratörünüzü seçin, bilgileri girin, Bağlantıyı dene ile hesabınızı sınayın. Deneme fatura kesmez.', 'Sevkiyat penceresindeki **Sevk edilen miktar kadar fatura kes (e-Fatura / e-Arşiv)** kutusu ve **Sevkiyatlar** sekmesindeki **Faturala** düğmesi belgeyi entegratöre gönderir. Sağlayıcının altındaki Kapsam notunu okuyun.', 'Belge **e-Belgeler** sayfasında görünür, durumu **Sevkiyatlar** sekmesinde izlenir.', 'Simülasyon seçiliyse belge TEST olarak oluşur, GİB’e gitmez. **Faturala** düğmesi satırda kalır.'], sorun: ['e-Belge oluşturulmadı uyarısında alıcının vergi numarasını kontrol edin, gerekirse Bağlantıyı dene adımını yineleyin.'] },
    eirsaliye: { degisir: ['Bu bağlantı NEBSOFT ile iletişime geçerek açtırılır. **Entegrasyonlar** sayfasında kartı açıp iletişim talebi bırakın.', 'Açıldıktan sonra sevkiyat, fason ve iade pencerelerindeki e-İrsaliye kutusu belgeyi iletir, numarası fişe yazılır.', 'Açılana kadar GİB’e e-İrsaliye gönderilmez. e-Fatura simülasyondaysa kutu **e-Belgeler** sayfasında TEST belge oluşturur. e-Fatura için Uyumsoft, Paraşüt veya Nilvera bağlıysa kutu hata uyarısı verir, sevkiyat yine kaydedilir.', 'İrsaliyeyi entegratör panelinden düzenleyin. Sevk fişi irsaliye yerine geçmez.'], sorun: ['Fişte **TEST — gönderilmedi** yazıyorsa belge GİB’e gitmemiştir.'] },
    emustahsil: { degisir: ['Bu bağlantı NEBSOFT ile iletişime geçerek açtırılır. **Entegrasyonlar** sayfasında kartı açıp iletişim talebi bırakın.', 'Açıldıktan sonra tedarikçi kartında **Çiftçi / üretici (e-Müstahsil makbuzu kesilir)** işaretliyse mal kabul kaydedilince makbuz iletilir. Stopaj oranı kurulumda girilir.', 'Açılana kadar makbuz gönderilmez. Kutuyu işaretlemek tek başına makbuz kesmez. Makbuzu entegratör panelinden düzenleyin.'], sorun: ['**e-Müstahsil makbuzu TEST: simülasyonda, gönderilmedi** uyarısında makbuz düzenlenmemiştir.'] },
    kantar: { degisir: ['Entegre et ile **Seri port (RS-232 / USB)** veya **Ağ indikatörü (TCP)** seçin, bilgileri girin, Bağlantıyı dene ile indikatörden gerçek ağırlık okuyun.', '**Mal Kabul** penceresinde **Oku** düğmeleri brüt ve dara ağırlığı yazar. Net ve irsaliye farkı hesaplanır, fark %1’i aşarsa kırmızı olur.', 'Bu okuma yalnız mal kabuldedir, sevkiyat penceresinde kantar yoktur. **Elle giriş** seçilirse değerleri kendiniz yazarsınız.'], sorun: ['Ağırlık okunamayınca program elle sorar. Tartımı yazıp devam edin, bağlantı ayarını sihirbazdan yeniden deneyin.'] },
    plc: { degisir: ['Entegre et ile **Modbus TCP** veya **MQTT** seçin, okuma noktalarını girin, Bağlantıyı dene ile değerleri okuyun. PLC’ye hiçbir şey yazılmaz.', '**Bakım & OEE** sayfasındaki **Makine sayaçlarını oku** her istasyonun sayacını makine kartında gösterir, son okumadan beri artışı yazar.', 'Okuma elle yapılır. Sayaç OEE, üretim bildirimi ve duruş kaydına girmez, sıfırlanmaz. Üretimi ve duruşu **Operatör Ekranı** ile girmeye devam edin.', '**Operatör girişi** seçilirse okuma yapılmaz.'], sorun: ['Okuma noktalarından değer gelmedi uyarısında istasyon kodlarını **İstasyon tanımları** sekmesiyle karşılaştırın.', '**Okuma noktası tanımlı değil** hatasında kurulumdaki **Okuma noktaları** alanını doldurun.'] },
    sms: { degisir: ['Entegre et ile sağlayıcınızı seçin, bilgileri girin, Bağlantıyı dene ile hesabınızı sınayın. Deneme SMS göndermez, kredi harcamaz.', 'Sevkiyat penceresindeki **Müşteriye SMS ile bildir** kutusu sevki bildirir. Bayi siparişinde **Onayla** bayiye mesaj gönderir.', 'Simülasyonda sonuç TEST olarak bildirilir, müşteriye bir şey gitmez.'], sorun: ['Hata çıkıyorsa sağlayıcı panelindeki kredi ve onaylı başlık bilgisini kontrol edin.'] },
    email: { degisir: ['Entegre et ile sağlayıcınızı seçin, bilgileri girin, Bağlantıyı dene ile hesabınızı sınayın. Deneme e-posta göndermez.', '**Satınalma** sayfasındaki siparişte zarf simgesi metni tedarikçiye gönderir. Sağlayıcı bağlı değilse bilgisayarınızdaki e-posta programı açılır, gönderimi siz yaparsınız.', 'Entegratöre iletilen e-Arşiv faturası, müşterinin e-postası varsa ona da gönderilir.'], sorun: ['Gönderilemedi uyarısında sağlayıcı bilgilerini sihirbazdan yeniden deneyin.'] },
